import re,json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
entries=json.loads((root/'shards/early_existing_bib.json').read_text())
def field(entry,name,value):
    m=re.search(r'\b'+re.escape(name)+r'\s*=\s*\{',entry)
    if not m:return entry[:-1].rstrip().rstrip(',')+',\n  '+name+' = {'+value+'}\n}'
    depth=1;i=m.end()
    while depth:
        if entry[i]=='{' and entry[i-1]!='\\':depth+=1
        if entry[i]=='}' and entry[i-1]!='\\':depth-=1
        i+=1
    return entry[:m.start()]+name+' = {'+value+'}'+entry[i:]
def update(key,annote,url=None,note='verified'):
    entry=entries[key]
    for n,v in [('annote',annote),('note',note)]:entry=field(entry,n,v)
    if url:entry=field(entry,'url',url)
    entries[key]=entry
def add(typ,key,**d):
    d.setdefault('note','verified')
    entries[key]='@'+typ+'{'+key+',\n'+',\n'.join('  '+k+' = {'+str(v)+'}' for k,v in d.items())+'\n}'

